WITH base AS (SELECT id, order_id, method, paid_at, status, DATE_FORMAT(paid_at, 'yyyy-MM') paid_at_label, TRIM(method) clean_method, COALESCE(method, 'DIRECT') method_filled FROM payments WHERE paid_at > DATE '2023-06-02' AND status IN ('FAILED', 'SUCCESS', 'REFUNDED')), with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM base), sessions_payments AS (SELECT id, order_id, paid_at, paid_at_label, clean_method, method_filled, SUM(is_new_burst) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps), flagged AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC) > INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM sessions_payments), sessionized AS (SELECT id, order_id, paid_at, method_filled, SUM(is_new_session) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged), matched_keys AS (SELECT order_id FROM sessionized EXCEPT SELECT order_id FROM payments WHERE amount > 1250), reconciled AS (SELECT s.* FROM sessionized s JOIN matched_keys k ON s.order_id = k.order_id), filtered AS (SELECT *, ROUND(island_id, 0) island_id_rounded, ROUND(island_id * 1.1, 2) island_id_adjusted FROM reconciled WHERE paid_at > DATE '2023-09-12' AND order_id IS NOT NULL), metrics AS (SELECT method_filled, island_id_adjusted, COUNT(island_id_rounded) OVER (ORDER BY CAST(paid_at AS BIGINT) ASC RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) island_id_rounded_count_7d, AVG(island_id) OVER (PARTITION BY YEAR(paid_at), order_id) paid_at_year_avg_island_id, COUNT(island_id) OVER (PARTITION BY order_id ORDER BY CAST(paid_at AS BIGINT) ASC RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) island_id_count_90d FROM filtered WHERE order_id IS NULL) SELECT island_id_adjusted, island_id_count_90d FROM metrics ORDER BY island_id_adjusted ASC
